let gameAudio=null,gameAudioBus=null,soundMuted=false,lastPetalSound=-Infinity,lastPlayerSound=-Infinity;
try{soundMuted=localStorage.getItem('bloomfall-muted')==='true';}catch{}
function unlockGameAudio(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!gameAudio){gameAudio=new Audio();gameAudioBus=gameAudio.createGain();gameAudioBus.gain.value=soundMuted?0:.16;const limiter=gameAudio.createDynamicsCompressor();limiter.threshold.value=-18;limiter.ratio.value=8;gameAudioBus.connect(limiter);limiter.connect(gameAudio.destination);}if(gameAudio.state==='suspended')gameAudio.resume().catch(()=>{});}catch{}}
function renderSoundButton(){const b=document.getElementById('sound-toggle');if(b){b.textContent=soundMuted?'♪ Sound off':'♫ Sound on';b.setAttribute('aria-pressed',String(!soundMuted));}}
function toggleGameSound(){soundMuted=!soundMuted;unlockGameAudio();if(gameAudioBus)gameAudioBus.gain.value=soundMuted?0:.16;try{localStorage.setItem('bloomfall-muted',String(soundMuted));}catch{}renderSoundButton();}
function playHitSound(kind){if(soundMuted||!gameAudio||gameAudio.state!=='running')return;const now=gameAudio.currentTime,petal=kind==='petal';if(now-(petal?lastPetalSound:lastPlayerSound)<(petal?.055:.02))return;if(petal)lastPetalSound=now;else lastPlayerSound=now;try{const osc=gameAudio.createOscillator(),gain=gameAudio.createGain();osc.type=petal?'triangle':'square';osc.frequency.setValueAtTime(petal?880:125,now);osc.frequency.exponentialRampToValueAtTime(petal?360:48,now+(petal?.055:.11));gain.gain.setValueAtTime(.001,now);gain.gain.exponentialRampToValueAtTime(petal?.35:.45,now+.004);gain.gain.exponentialRampToValueAtTime(.001,now+(petal?.065:.13));osc.connect(gain);gain.connect(gameAudioBus);osc.start(now);osc.stop(now+.15);osc.onended=()=>{osc.disconnect();gain.disconnect();};}catch{}}
document.addEventListener('DOMContentLoaded',()=>{document.getElementById('sound-toggle').onclick=toggleGameSound;renderSoundButton();});
